class FreshDecisionEvidenceTests(unittest.TestCase):
 @classmethod
 def setUpClass(cls):cls.data=r.p.read(r.DEFAULT)
 def reject(self,data):
  with self.assertRaises((ValueError,KeyError,TypeError,AssertionError)):r.replay(data)
 def test_closed_actual_counters_usage_and_cohort_denominators_replay_without_service(self):
  with patch('runaway.generation.codex_generate',side_effect=AssertionError('No service'))as backend:out=r.check()
  backend.assert_not_called()
  for key in ('actual_original_attempts','actual_original_children','missing_original_usage','unused_slots_expire','known_original_usage'):
   self.assertEqual(out[key],EXPECTED[key])
  self.assertEqual(out['summary'],EXPECTED['summary'])
  self.assertEqual([x['characters']for x in out['cards']],EXPECTED['characters'])
  self.assertEqual(sum(x['actual_calls']for x in out['usage_by_stage'].values()),out['actual_original_attempts'])
  for view in r.p.VIEWS:
   self.assertEqual(out['summary']['joint'][view]['joint']['planned'],64)
   self.assertEqual(out['summary']['joint'][view]['known']['planned'],48)
   self.assertEqual(out['summary']['joint'][view]['unknown']['planned'],16)
   for group in out['summary']['cohort_slices'].values():self.assertEqual(group[view]['joint']['planned'],16)
 def test_source_reference_questions_and_implementation_cannot_change(self):
  for name in ('sources.json','reference.private.json','queries.public.json','author-evidence.private.json','implementation-sha256.json'):
   data=copy.deepcopy(self.data);data['prepared_files'][name]={};self.reject(data)
  for name in ('scientific_source_ref','input_manifest_sha256'):
   data=copy.deepcopy(self.data);data[name]='foreign';self.reject(data)
 def test_attempts_cannot_be_duplicated_or_relabelled_as_another_parent(self):
  data=copy.deepcopy(self.data);data['records'].append(copy.deepcopy(data['records'][0]));self.reject(data)
  data=copy.deepcopy(self.data);rec=data['records'][0];rec['profile']='foreign';rec['execution_record']['profile']='foreign';self.reject(data)
  data=copy.deepcopy(self.data);rec=data['records'][0];rec['generation_repeat']=1;rec['execution_record']['generation_repeat']=1;self.reject(data)
 def test_raw_answers_and_available_artifacts_cannot_be_repaired(self):
  data=copy.deepcopy(self.data);raw=next((x for x in data['records']if x['raw_present']),None)
  if raw is not None:
   raw['raw']+='changed';self.reject(data)
  else:
   data['records'][0]['raw']='invented';self.reject(data)
  artifact=next((x for x in self.data['records']if x['artifact']is not None),None)
  if artifact is not None:
   data=copy.deepcopy(self.data);rec=next(x for x in data['records']if x['artifact']is not None)
   rec['artifact']['prompt']+='manual repair';self.reject(data)
  else:self.assertFalse(any(x['artifact']is not None for x in self.data['records']))
 def test_own_tail_rule_cannot_be_removed_or_replaced_with_card_material(self):
  data=copy.deepcopy(self.data);data['prepared_files']['dynamic-rules.json']['only_own_generation_parent']=False;self.reject(data)
  tail=next((x for x in self.data['records']if x['kind']=='read'and x['view']=='tail'),None)
  if tail is not None:
   data=copy.deepcopy(self.data);tail=next(x for x in data['records']if x['slot']==tail['slot'])
   tail['request']['prompt']+='foreign material';tail['request_sha256']=r.p.digest(tail['request']);tail['execution_record']['request_sha256']=tail['request_sha256'];self.reject(data)
 def test_joint_generation_cohort_and_missing_denominators_cannot_shrink(self):
  for fault in ('joint','generation','cohort','closed'):
   data=copy.deepcopy(self.data)
   if fault=='joint':data['status']['scores']['joint']['card']['joint']['planned']-=1
   elif fault=='generation':data['status']['scores']['per_generation']['0']['card']['joint']['planned']-=1
   elif fault=='cohort':data['status']['scores']['cohort_slices']['ordinary']['card']['joint']['planned']-=1
   else:data['status']['scope_closed']=False
   self.reject(data)
 def test_usage_attempts_and_child_ledger_cannot_be_rewritten(self):
  for fault in ('usage','attempt','child'):
   data=copy.deepcopy(self.data)
   if fault=='usage':data['status']['known_usage']['total_tokens']=data['status']['known_usage'].get('total_tokens',0)+1
   elif fault=='attempt':data['status']['attempt_reservations']-=1
   else:data['records'][0]['local_cli_child_intent']=not data['records'][0]['local_cli_child_intent']
   self.reject(data)
 def test_private_fields_and_unsupported_generalization_claims_are_rejected(self):
  for field in r.FALSE_CLAIMS:
   data=copy.deepcopy(self.data);data[field]=True;self.reject(data)
  data=copy.deepcopy(self.data);data['human_grant']='PRIVATE';self.reject(data)
  data=copy.deepcopy(self.data);data['records'][0]['credentials']='PRIVATE';self.reject(data)
 def test_unknown_loss_classification_never_turns_missing_into_abstention(self):
  for gold,values,expected in [('A',[None,'U'],'missing'),('A',['U','U'],'all_unknown_from_known'),
   ('A',['A','U'],'intermittent_unknown_from_known'),('A',['U','B'],'mixed_unknown_and_different_choice'),
   ('A',['A','B'],'different_choice_from_known'),('U',['U','A'],'choice_when_reference_unknown'),
   ('U',['U','U'],'retained'),('A',['A','A'],'retained')]:self.assertEqual(r.loss_kind(gold,values),expected)
